INSERT INTO public.questions (skill, cefr_level, type, context_tag, prompt_text, options, correct_answer, explanation) VALUES
  ('grammar_vocab', 'A1', 'mcq', 'tenses', 'Our company _____ software for banks; that''s our main business.', to_jsonb(ARRAY['makes','is making','made','will make']::text[]), 'makes', 'Present simple states a general, permanent fact about the business, not a temporary or one-time action.'),
  ('grammar_vocab', 'A1', 'mcq', 'tenses', 'We usually use email, but this week we _____ the phones because the server is down.', to_jsonb(ARRAY['are using','use','used','will use']::text[]), 'are using', 'Present continuous with ''this week'' shows a temporary situation, contrasted with the usual routine of using email.'),
  ('grammar_vocab', 'A1', 'mcq', 'tenses', 'The photocopier is broken, so Anna _____ the documents by hand today.', to_jsonb(ARRAY['is copying','copies','copied','will copy']::text[]), 'is copying', 'Present continuous with ''today'' describes a temporary action happening now because of the broken photocopier, not Anna''s usual routine.'),
  ('grammar_vocab', 'A2', 'mcq', 'tenses', 'While Tom _____ the report, the printer suddenly ran out of paper.', to_jsonb(ARRAY['was writing','wrote','writes','has written']::text[]), 'was writing', 'Past continuous describes the longer background action in progress when the shorter past simple event interrupted it.'),
  ('grammar_vocab', 'A2', 'mcq', 'tenses', 'The phone rang while she _____ lunch with a client.', to_jsonb(ARRAY['was having','had','has','will have']::text[]), 'was having', 'Past continuous shows the action already in progress at the moment the past simple event happened.'),
  ('grammar_vocab', 'A2', 'mcq', 'tenses', 'Look at the sky! It _____ rain any second now.', to_jsonb(ARRAY['is about to','rains','rained','will have rained']::text[]), 'is about to', '''Be about to'' expresses an action expected in the very near future, signalled here by ''any second now.'''),
  ('grammar_vocab', 'B1', 'mcq', 'tenses', 'Don''t call at 9 p.m. - I _____ dinner with my family at that exact moment, so I won''t hear the phone ring.', to_jsonb(ARRAY['will be having','will have','have','had']::text[]), 'will be having', 'Future continuous describes an action that will already be in progress at a specific point in the future.'),
  ('grammar_vocab', 'B1', 'mcq', 'tenses', 'I _____ that report yesterday.', to_jsonb(ARRAY['wrote','have written','have been writing','was writing']::text[]), 'wrote', 'The definite past time marker ''yesterday'' requires the past simple, not the present perfect, which is used for unspecified past time.'),
  ('grammar_vocab', 'B1', 'mcq', 'tenses', 'She _____ three contracts so far this month.', to_jsonb(ARRAY['has signed','signed','was signing','had signed']::text[]), 'has signed', '''So far this month'' refers to an unfinished time period, which requires the present perfect rather than the past simple.'),
  ('grammar_vocab', 'B2', 'mcq', 'tenses', 'The technician _____ the printer already - it''s working perfectly now.', to_jsonb(ARRAY['has fixed','has been fixing','fixes','was fixing']::text[]), 'has fixed', 'Present perfect simple emphasises the completed result (''working perfectly now''), unlike the continuous form which suggests the repair is still unfinished.'),
  ('grammar_vocab', 'B2', 'mcq', 'tenses', 'He _____ five cups of coffee since breakfast, which is why he''s so anxious.', to_jsonb(ARRAY['has had','has been having','had','was having']::text[]), 'has had', '''Since breakfast'' requires the present perfect, and a specific countable quantity like ''five cups'' is expressed with the simple, not the continuous, form.'),
  ('grammar_vocab', 'B2', 'mcq', 'tenses', 'I don''t cut my own hair - I _____ every month at the salon.', to_jsonb(ARRAY['have it cut','cut it','am cutting it','have cut it']::text[]), 'have it cut', 'The causative ''have something done'' shows that someone else performs the action for the subject.'),
  ('grammar_vocab', 'C1', 'mcq', 'tenses', 'He told me on Monday, ''I''ll finish the report tomorrow.'' He said he would finish the report _____.', to_jsonb(ARRAY['the next day','tomorrow','yesterday','the previous day']::text[]), 'the next day', 'In reported speech, time expressions shift back one step from the moment of speaking, so ''tomorrow'' becomes ''the next day.'''),
  ('grammar_vocab', 'C1', 'mcq', 'tenses', 'She asked me, ''Where do you live?'' She asked me _____.', to_jsonb(ARRAY['where I lived','where do I live','where did I live','where I live']::text[]), 'where I lived', 'Reported questions use normal statement word order with no inversion and backshift the tense, so ''do you live'' becomes ''I lived.'''),
  ('grammar_vocab', 'C1', 'mcq', 'tenses', 'If he _____ so fast, he wouldn''t have crashed into the barrier.', to_jsonb(ARRAY['hadn''t been driving','doesn''t drive','didn''t drive','wasn''t driving']::text[]), 'hadn''t been driving', 'The third conditional requires the past perfect in the if-clause to describe a hypothetical past situation; ''doesn''t drive'' and ''didn''t drive'' are the wrong tense entirely, and ''wasn''t driving'' (past continuous, not perfect) doesn''t fit the third-conditional structure.'),
  ('grammar_vocab', 'C2', 'mcq', 'tenses', 'The lights are off and her car is gone - she _____ home already.', to_jsonb(ARRAY['must have gone','must go','had to go','should go']::text[]), 'must have gone', '''Must have + past participle'' expresses a confident deduction about a completed past action based on present evidence.'),
  ('grammar_vocab', 'C2', 'mcq', 'tenses', 'According to the original schedule, the CEO _____ the keynote, but the event was cancelled at the last moment.', to_jsonb(ARRAY['was to have given','will give','gives','had given']::text[]), 'was to have given', '''Was to have + past participle'' describes a formally arranged past plan that was never carried out.'),
  ('grammar_vocab', 'C2', 'mcq', 'tenses', 'No sooner _____ his resignation than three competitors offered him a job.', to_jsonb(ARRAY['had he submitted','he had submitted','did he submit','he submitted']::text[]), 'had he submitted', 'After the negative adverbial ''No sooner,'' the auxiliary and subject invert and the past perfect marks the earlier action.'),
  ('grammar_vocab', 'A1', 'mcq', 'prepositions', 'We arrived _____ London last night after a long flight.', to_jsonb(ARRAY['in','at','on','to']::text[]), 'in', '''Arrive in'' is used before cities and countries, while ''arrive at'' is used for specific smaller places such as buildings or stations.'),
  ('grammar_vocab', 'A1', 'mcq', 'prepositions', 'The plane arrived _____ the airport ten minutes early.', to_jsonb(ARRAY['at','in','on','to']::text[]), 'at', '''Arrive at'' is used for specific points such as airports, stations, or buildings, while ''arrive in'' is used for cities and countries.'),
  ('grammar_vocab', 'A1', 'mcq', 'prepositions', 'The 9 a.m. train arrived exactly _____ time, not a minute late.', to_jsonb(ARRAY['on','in','at','by']::text[]), 'on', '''On time'' means punctual, exactly at the scheduled moment; ''in time'' means with enough time to spare before something happens.'),
  ('grammar_vocab', 'A2', 'mcq', 'prepositions', 'Please book your seat _____ advance because tickets sell out quickly.', to_jsonb(ARRAY['in','on','at','for']::text[]), 'in', '''In advance'' is a fixed time expression meaning before something happens.'),
  ('grammar_vocab', 'A2', 'mcq', 'prepositions', 'Maria is _____ charge of answering the phones this week.', to_jsonb(ARRAY['in','on','at','for']::text[]), 'in', '''In charge of'' is a fixed expression meaning responsible for managing something.'),
  ('grammar_vocab', 'A2', 'mcq', 'prepositions', 'We got to the cinema just _____ time to see the start of the film.', to_jsonb(ARRAY['in','on','at','for']::text[]), 'in', '''In time to do something'' means with enough time to do it; ''on time'' means punctual and does not combine naturally with a following infinitive.'),
  ('grammar_vocab', 'B1', 'mcq', 'prepositions', 'The training program consists _____ six separate modules.', to_jsonb(ARRAY['of','in','with','from']::text[]), 'of', 'The verb ''consist'' is always followed by the preposition ''of'' when describing what something is made up of.'),
  ('grammar_vocab', 'B1', 'mcq', 'prepositions', 'Our company specializes _____ providing translation services for international clients.', to_jsonb(ARRAY['in','on','at','with']::text[]), 'in', '''Specialize'' is followed by the preposition ''in'' when referring to a particular area of expertise.'),
  ('grammar_vocab', 'B1', 'mcq', 'prepositions', 'The manager insisted _____ reviewing the contract before it was signed.', to_jsonb(ARRAY['on','in','at','for']::text[]), 'on', '''Insist'' takes the preposition ''on'' when referring to something someone firmly requires.'),
  ('grammar_vocab', 'B2', 'mcq', 'prepositions', 'The support team is currently working _____ pressure to meet the deadline.', to_jsonb(ARRAY['under','in','on','at']::text[]), 'under', '''Under pressure'' is a fixed expression describing the state of being forced to work quickly or intensely.'),
  ('grammar_vocab', 'B2', 'mcq', 'prepositions', 'The assistant signed the contract _____ behalf of the director, who was traveling.', to_jsonb(ARRAY['on','in','for','at']::text[]), 'on', '''On behalf of'' is a fixed expression meaning acting as a representative of someone else.'),
  ('grammar_vocab', 'B2', 'mcq', 'prepositions', 'The company issued a statement _____ response to the customer complaints.', to_jsonb(ARRAY['in','on','at','for']::text[]), 'in', '''In response to'' is a fixed phrase meaning as a reaction to something.'),
  ('grammar_vocab', 'C1', 'mcq', 'prepositions', 'All new contracts are subject _____ approval by the legal department.', to_jsonb(ARRAY['to','of','with','for']::text[]), 'to', '''Subject to'' is a fixed adjective + preposition phrase meaning dependent on or conditional upon something.'),
  ('grammar_vocab', 'C1', 'mcq', 'prepositions', '_____ the event of a fire, employees must use the emergency exits.', to_jsonb(ARRAY['In','At','On','By']::text[]), 'In', '''In the event of'' is a formal fixed phrase meaning ''if X happens'', commonly used in official documents.'),
  ('grammar_vocab', 'C1', 'mcq', 'prepositions', 'The application was rejected _____ the grounds that it was submitted after the deadline.', to_jsonb(ARRAY['on','in','at','by']::text[]), 'on', '''On the grounds that'' is a fixed formal phrase meaning ''for the reason that'', used to justify decisions.'),
  ('grammar_vocab', 'C2', 'mcq', 'prepositions', 'The refund was processed _____ the terms outlined in Section 4 of the contract.', to_jsonb(ARRAY['pursuant to','with regard to','in spite of','regardless of']::text[]), 'pursuant to', '''Pursuant to'' is a formal, legalistic phrase meaning ''in accordance with'' or ''as required by''; ''with regard to'' only introduces a topic and doesn''t express compliance, while ''in spite of'' and ''regardless of'' both wrongly imply the terms were disregarded.'),
  ('grammar_vocab', 'C2', 'mcq', 'prepositions', 'Bonus payments are awarded _____ the discretion of senior management.', to_jsonb(ARRAY['at','on','in','by']::text[]), 'at', '''At the discretion of'' is a fixed formal phrase meaning that a decision is left to someone''s judgment.'),
  ('grammar_vocab', 'C2', 'mcq', 'prepositions', 'Staff who work on public holidays receive a day off _____ lieu of overtime pay.', to_jsonb(ARRAY['in','on','at','for']::text[]), 'in', '''In lieu of'' is a formal fixed phrase meaning ''instead of''.'),
  ('grammar_vocab', 'A1', 'mcq', 'business_vocab', 'I work in an _____ near the train station.', to_jsonb(ARRAY['office','kitchen','garden','forest']::text[]), 'office', 'An office is a room or building where people do administrative work.'),
  ('grammar_vocab', 'A1', 'mcq', 'business_vocab', 'Please put the documents in the _____ on my desk.', to_jsonb(ARRAY['folder','umbrella','sandwich','bicycle']::text[]), 'folder', 'A folder is a container used to organize and store documents.'),
  ('grammar_vocab', 'A1', 'mcq', 'business_vocab', 'Keep the _____ in case you need to return the item.', to_jsonb(ARRAY['receipt','ladder','balloon','pillow']::text[]), 'receipt', 'A receipt is a printed record proving that a purchase was made.'),
  ('grammar_vocab', 'A2', 'mcq', 'business_vocab', 'My _____ checks my work every afternoon before I go home.', to_jsonb(ARRAY['supervisor','tourist','patient','musician']::text[]), 'supervisor', 'A supervisor is a person who oversees and manages employees'' work.'),
  ('grammar_vocab', 'A2', 'mcq', 'business_vocab', 'The company stores its products in a large _____ outside the city.', to_jsonb(ARRAY['warehouse','aquarium','cathedral','theatre']::text[]), 'warehouse', 'A warehouse is a large building used for storing goods before distribution.'),
  ('grammar_vocab', 'A2', 'mcq', 'business_vocab', 'You should ask the finance _____ about your expenses.', to_jsonb(ARRAY['department','orchestra','volcano','harbour']::text[]), 'department', 'A department is a division within an organization responsible for a specific area.'),
  ('grammar_vocab', 'B1', 'mcq', 'business_vocab', 'The company signed a new contract with a coffee _____ for the office.', to_jsonb(ARRAY['vendor','sailor','dentist','poet']::text[]), 'vendor', 'A vendor is a person or company that sells goods or services.'),
  ('grammar_vocab', 'B1', 'mcq', 'business_vocab', 'We need to count all the items in _____ before the end of the month.', to_jsonb(ARRAY['inventory','poetry','gravity','symphony']::text[]), 'inventory', 'Inventory is the total stock of goods a business holds.'),
  ('grammar_vocab', 'B1', 'mcq', 'business_vocab', 'Each salesperson must reach a monthly _____ of ten new clients.', to_jsonb(ARRAY['quota','melody','avalanche','apology']::text[]), 'quota', 'A quota is a fixed target amount that must be achieved.'),
  ('grammar_vocab', 'B2', 'mcq', 'business_vocab', 'The _____ team plans how products move from the factory to the shops.', to_jsonb(ARRAY['logistics','folklore','cartography','choreography']::text[]), 'logistics', 'Logistics refers to the coordination of moving goods and resources.'),
  ('grammar_vocab', 'B2', 'mcq', 'business_vocab', 'The company''s _____ moved from Paris to Lyon last year.', to_jsonb(ARRAY['headquarters','aquarium','monastery','greenhouse']::text[]), 'headquarters', 'Headquarters is the main office from which an organization is run.'),
  ('grammar_vocab', 'B2', 'mcq', 'business_vocab', 'The parent company owns a small _____ in Germany that handles local sales.', to_jsonb(ARRAY['subsidiary','sanctuary','tributary','monastery']::text[]), 'subsidiary', 'A subsidiary is a company that is controlled by a larger parent company.'),
  ('grammar_vocab', 'C1', 'mcq', 'business_vocab', 'The startup used its strong brand to _____ better terms with investors.', to_jsonb(ARRAY['leverage','evaporate','decorate','whistle']::text[]), 'leverage', 'To leverage something means to use it strategically to gain an advantage.'),
  ('grammar_vocab', 'C1', 'mcq', 'business_vocab', 'Merging the two teams created a real _____ that boosted overall productivity.', to_jsonb(ARRAY['synergy','monotony','symmetry','lethargy']::text[]), 'synergy', 'Synergy is the extra benefit gained when combined elements work more effectively together.'),
  ('grammar_vocab', 'C1', 'mcq', 'business_vocab', 'The finance team set aside a _____ fund in case sales fall unexpectedly.', to_jsonb(ARRAY['contingency','ceremony','testimony','matrimony']::text[]), 'contingency', 'A contingency fund is money reserved to cover unexpected future events.'),
  ('grammar_vocab', 'C2', 'mcq', 'business_vocab', 'Shareholders received a higher _____ this year after record profits.', to_jsonb(ARRAY['dividend','sediment','condiment','ligament']::text[]), 'dividend', 'A dividend is a portion of company profit paid out to shareholders.'),
  ('grammar_vocab', 'C2', 'mcq', 'business_vocab', 'Rising debts pushed the small firm toward _____ within two years.', to_jsonb(ARRAY['insolvency','benevolence','adolescence','turbulence']::text[]), 'insolvency', 'Insolvency is the state of being unable to pay debts owed.'),
  ('grammar_vocab', 'C2', 'mcq', 'business_vocab', 'As trustee, she has a _____ duty to act in the client''s best financial interest.', to_jsonb(ARRAY['fiduciary','hereditary','sedentary','itinerant']::text[]), 'fiduciary', 'Fiduciary describes a legal duty to act in someone else''s best interest.'),
  ('grammar_vocab', 'A1', 'mcq', 'phrasal_verbs', 'The teacher said goodbye and _____ the phone at the end of the call.', to_jsonb(ARRAY['hung up','picked up','turned on','filled in']::text[]), 'hung up', '"Hang up" means to end a telephone call.'),
  ('grammar_vocab', 'A1', 'mcq', 'phrasal_verbs', '"Could you _____ for a moment, please? I need to find your file."', to_jsonb(ARRAY['hold on','hand in','sign up','log in']::text[]), 'hold on', '"Hold on" means to wait for a short time.'),
  ('grammar_vocab', 'A1', 'mcq', 'phrasal_verbs', 'The office door was open, so the visitor decided to _____ and wait for the manager.', to_jsonb(ARRAY['come in','check in','print out','hang up']::text[]), 'come in', '"Come in" means to enter a room or place.'),
  ('grammar_vocab', 'A2', 'mcq', 'phrasal_verbs', 'You need to _____ to the company portal with your username and password before you can see your payslip.', to_jsonb(ARRAY['log in','sign up','check in','hold on']::text[]), 'log in', '"Log in" means to enter a computer system using your credentials.'),
  ('grammar_vocab', 'A2', 'mcq', 'phrasal_verbs', 'Passengers must _____ at the airport counter at least two hours before their flight.', to_jsonb(ARRAY['check in','sign up','log in','come in']::text[]), 'check in', '"Check in" means to register your arrival, for example at an airport or hotel.'),
  ('grammar_vocab', 'A2', 'mcq', 'phrasal_verbs', 'If you want to join the Friday training course, you have to _____ before Wednesday.', to_jsonb(ARRAY['sign up','log in','check in','hang up']::text[]), 'sign up', '"Sign up" means to register or enrol for something.'),
  ('grammar_vocab', 'B1', 'mcq', 'phrasal_verbs', 'The customer service team is trained to _____ complaints quickly and politely.', to_jsonb(ARRAY['deal with','run into','cut back on','log in']::text[]), 'deal with', '"Deal with" means to handle a problem or situation.'),
  ('grammar_vocab', 'B1', 'mcq', 'phrasal_verbs', 'Halfway through the product launch, the team _____ a technical problem that nobody had predicted.', to_jsonb(ARRAY['ran into','cut back on','dealt with','checked in']::text[]), 'ran into', '"Run into" means to unexpectedly encounter a problem or difficulty.'),
  ('grammar_vocab', 'B1', 'mcq', 'phrasal_verbs', 'To save money this quarter, management decided to _____ business travel.', to_jsonb(ARRAY['cut back on','run into','deal with','sign up']::text[]), 'cut back on', '"Cut back on" means to reduce the amount of something.'),
  ('grammar_vocab', 'B2', 'mcq', 'phrasal_verbs', 'During the review, the auditor _____ several inconsistencies in the budget report.', to_jsonb(ARRAY['pointed out','worked out','took over','cut back on']::text[]), 'pointed out', '"Point out" means to draw attention to a fact or detail.'),
  ('grammar_vocab', 'B2', 'mcq', 'phrasal_verbs', 'It took the finance team all week to _____ the total cost of the merger.', to_jsonb(ARRAY['work out','point out','take over','deal with']::text[]), 'work out', '"Work out" means to calculate or figure something out.'),
  ('grammar_vocab', 'B2', 'mcq', 'phrasal_verbs', 'When the CEO retired unexpectedly, her deputy _____ the day-to-day running of the company.', to_jsonb(ARRAY['took over','worked out','pointed out','ran into']::text[]), 'took over', '"Take over" means to assume control or responsibility from someone else.'),
  ('grammar_vocab', 'C1', 'mcq', 'phrasal_verbs', 'Everyone in the office agreed to _____ so they could buy the retiring manager a proper gift.', to_jsonb(ARRAY['chip in','tide over','spell out','take over']::text[]), 'chip in', '"Chip in" means to contribute money together with other people.'),
  ('grammar_vocab', 'C1', 'mcq', 'phrasal_verbs', 'The emergency credit line was only meant to _____ the business until regular orders picked up again.', to_jsonb(ARRAY['tide over','chip in','spell out','work out']::text[]), 'tide over', '"Tide over" means to help someone get through a difficult period temporarily.'),
  ('grammar_vocab', 'C1', 'mcq', 'phrasal_verbs', 'The new contract clearly _____ each party''s responsibilities to prevent future disputes.', to_jsonb(ARRAY['spells out','tides over','chips in','points out']::text[]), 'spells out', '"Spell out" means to explain something in clear, precise detail.'),
  ('grammar_vocab', 'C2', 'mcq', 'phrasal_verbs', 'The two departments spent the whole afternoon in a tense meeting trying to _____ their disagreement over the budget.', to_jsonb(ARRAY['thrash out','stem from','home in on','tide over']::text[]), 'thrash out', '"Thrash out" means to resolve a disagreement through lengthy, thorough discussion.'),
  ('grammar_vocab', 'C2', 'mcq', 'phrasal_verbs', 'Investigators concluded that the delay seemed to _____ a miscommunication between the two teams weeks earlier.', to_jsonb(ARRAY['stem from','home in on','thrash out','chip in']::text[]), 'stem from', '"Stem from" means to originate or result from something.'),
  ('grammar_vocab', 'C2', 'mcq', 'phrasal_verbs', 'After reviewing weeks of data, the analysts were finally able to _____ the exact cause of the sales drop.', to_jsonb(ARRAY['home in on','stem from','thrash out','spell out']::text[]), 'home in on', '"Home in on" means to focus attention precisely on something.'),
  ('grammar_vocab', 'A1', 'mcq', 'formal_register', 'You are meeting a new client for the first time in a formal business meeting. Which self-introduction is correct?', to_jsonb(ARRAY['Hi, I''m Alex, nice to meet you.','Good morning, my name is Alex Carter, I''m the Project Manager here.','Yo, I''m Alex.','Hey, Alex here, what''s up?']::text[]), 'Good morning, my name is Alex Carter, I''m the Project Manager here.', 'In a formal first meeting with a client, a full name and title with a polite greeting sets the right professional tone.'),
  ('grammar_vocab', 'A1', 'mcq', 'formal_register', 'You want to ask a close colleague to cover your shift tomorrow. You''re texting them casually. Which message is natural?', to_jsonb(ARRAY['Dear Colleague, I am writing to request that you cover my shift tomorrow.','Hey, could you cover my shift tomorrow? I owe you one!','To Whom It May Concern, please cover my shift.','I hereby request shift coverage for tomorrow.']::text[]), 'Hey, could you cover my shift tomorrow? I owe you one!', 'A casual text to a close colleague calls for friendly, informal language, not formal business phrasing.'),
  ('grammar_vocab', 'A1', 'mcq', 'formal_register', 'You''re chatting with a colleague from IT that you know well, asking for quick help with your laptop. Which message is appropriate?', to_jsonb(ARRAY['Hey, my laptop''s acting up again, got a sec?','Dear IT Department, I am writing to report a technical malfunction.','I would be most grateful if you could attend to my device at your earliest convenience.','To the IT Manager, kindly resolve this issue.']::text[]), 'Hey, my laptop''s acting up again, got a sec?', 'Chatting casually with a colleague you know well calls for relaxed, everyday language rather than formal request phrasing.'),
  ('grammar_vocab', 'A2', 'mcq', 'formal_register', 'You want to formally congratulate a colleague on their recent promotion in a company-wide email. Which sentence is appropriate?', to_jsonb(ARRAY['Congratulations on your promotion; your hard work has been well deserved.','Nice one, you finally got it!','OMG congrats, you totally earned this lol.','Heard you got bumped up, cool.']::text[]), 'Congratulations on your promotion; your hard work has been well deserved.', 'A company-wide email calls for polite, professional congratulations rather than casual slang.'),
  ('grammar_vocab', 'A2', 'mcq', 'formal_register', 'Your team just won a big client, and you''re posting in the informal team group chat. Which message fits?', to_jsonb(ARRAY['We are pleased to announce the successful acquisition of a new client.','Yes!! We did it, team, amazing work everyone!','I am writing to inform you that the client has been secured.','Please be advised that the client acquisition was successful.']::text[]), 'Yes!! We did it, team, amazing work everyone!', 'An informal team group chat calls for enthusiastic, casual celebration rather than formal announcement language.'),
  ('grammar_vocab', 'A2', 'mcq', 'formal_register', 'A colleague you''re friendly with invites you to lunch, but you''re busy. You''re replying informally. Which message is natural?', to_jsonb(ARRAY['I regret to inform you that I am unable to accept your invitation.','Can''t today, swamped with work, next time for sure!','Please be advised that I decline your lunch invitation.','I must respectfully decline due to prior commitments.']::text[]), 'Can''t today, swamped with work, next time for sure!', 'Replying informally to a friendly colleague calls for a light, casual decline rather than stiff formal wording.'),
  ('grammar_vocab', 'B1', 'mcq', 'formal_register', 'You need to formally email your manager to ask for more time on a project deadline. Which message is appropriate?', to_jsonb(ARRAY['Hey, any chance I can get a bit more time? Kinda swamped.','I am writing to request a short extension on the project deadline, as I need additional time to ensure the quality of the work.','Deadline''s tight, can we push it?','I demand more time to finish this project.']::text[]), 'I am writing to request a short extension on the project deadline, as I need additional time to ensure the quality of the work.', 'A formal email to a manager requires a polite, clearly explained request rather than casual or blunt phrasing.'),
  ('grammar_vocab', 'B1', 'mcq', 'formal_register', 'You need to send a formal email informing a client that your company''s prices will increase next quarter. Which sentence fits?', to_jsonb(ARRAY['Heads up, prices are going up next quarter.','We would like to inform you that, effective next quarter, our prices will be subject to a slight increase.','Prices up next quarter, sorry about that.','Just so you know, we''re charging more soon.']::text[]), 'We would like to inform you that, effective next quarter, our prices will be subject to a slight increase.', 'Notifying a client of a price change in a formal email requires clear, courteous business language, not casual phrasing.'),
  ('grammar_vocab', 'B1', 'mcq', 'formal_register', 'You want to ask a teammate you work closely with to quickly double-check your figures before a meeting. Which message is natural?', to_jsonb(ARRAY['Could you kindly verify the accuracy of the figures at your earliest convenience?','Hey, could you double-check these numbers before the meeting? Thanks!','I would be obliged if you would review the figures.','Please be so kind as to confirm the data herein.']::text[]), 'Hey, could you double-check these numbers before the meeting? Thanks!', 'Asking a close teammate for a quick favor calls for friendly, direct phrasing rather than stiff formal requests.'),
  ('grammar_vocab', 'B2', 'mcq', 'formal_register', 'You received a job offer and want to formally accept it by email. Which response is appropriate?', to_jsonb(ARRAY['Sounds good, I''m in!','I am delighted to accept the position and look forward to joining the team on the agreed start date.','Yep, count me in, when do I start?','Cool, works for me.']::text[]), 'I am delighted to accept the position and look forward to joining the team on the agreed start date.', 'Formally accepting a job offer by email calls for polite, professional phrasing that confirms the acceptance clearly.'),
  ('grammar_vocab', 'B2', 'mcq', 'formal_register', 'You''re setting up an out-of-office auto-reply for external clients and business contacts. Which message is appropriate?', to_jsonb(ARRAY['Not around, back soon, ping me later.','Thank you for your email. I am currently out of the office and will respond upon my return on Monday.','I''m off, catch you next week!','Gone for a bit, message will get lost, sorry.']::text[]), 'Thank you for your email. I am currently out of the office and will respond upon my return on Monday.', 'An auto-reply seen by external clients should stay professional and clear, not casual or vague.'),
  ('grammar_vocab', 'B2', 'mcq', 'formal_register', 'You''re texting a colleague you''re friendly with to confirm drinks after work. Which message is natural?', to_jsonb(ARRAY['I am writing to confirm our arrangement to meet following the conclusion of the working day.','Still on for drinks later? See you at 6!','Please confirm your availability for a post-work social engagement.','Kindly advise whether you remain amenable to the proposed gathering.']::text[]), 'Still on for drinks later? See you at 6!', 'Texting a friendly colleague about after-work plans calls for a casual, natural tone, not formal business wording.'),
  ('grammar_vocab', 'C1', 'mcq', 'formal_register', 'After your performance review, you want to formally email your manager asking for more detailed feedback on your development areas. Which message is most appropriate?', to_jsonb(ARRAY['Can you tell me more about what I need to work on?','Give me more details on what I''m doing wrong.','Following our recent review, I would appreciate the opportunity to discuss my development areas in more detail, if convenient.','Just wondering what else you want from me.']::text[]), 'Following our recent review, I would appreciate the opportunity to discuss my development areas in more detail, if convenient.', 'A formal follow-up email to a manager should be polite and structured, clearly referencing the review and using hedging language like ''if convenient'' rather than a direct, unstructured question.'),
  ('grammar_vocab', 'C1', 'mcq', 'formal_register', 'You are drafting a company-wide email formally introducing a new remote-work policy to all staff. Which opening is most appropriate?', to_jsonb(ARRAY['So here''s the deal with remote work now.','We are writing to inform you of an important update to our remote-work policy, effective from next month.','New rule: remote work is changing, read below.','Heads up team, policy''s changing, don''t freak out.']::text[]), 'We are writing to inform you of an important update to our remote-work policy, effective from next month.', 'A company-wide policy announcement should use formal, precise language that clearly signals an official update.'),
  ('grammar_vocab', 'C1', 'mcq', 'formal_register', 'You are writing a formal year-end email thanking a long-standing client for their continued business. Which closing message is most appropriate?', to_jsonb(ARRAY['Thanks for sticking with us all year, you''re the best!','We sincerely thank you for your continued trust and partnership throughout the year and look forward to working with you further.','Cheers for another good year, catch you in January.','We appreciate you not leaving us for a competitor this year.']::text[]), 'We sincerely thank you for your continued trust and partnership throughout the year and look forward to working with you further.', 'A formal year-end message to a long-standing client should express sincere, professional gratitude without casual or awkward phrasing.'),
  ('grammar_vocab', 'C2', 'mcq', 'formal_register', 'You''re frustrated with a client''s last-minute request and want to vent to a close colleague privately. Even informally, which message crosses a professionalism boundary and should be avoided?', to_jsonb(ARRAY['Honestly, this client''s timing drives me up the wall sometimes.','That client is such an idiot, I can''t believe they''re still in business.','Ugh, another last-minute change, typical.','Feeling a bit frustrated with this client today, need a coffee break.']::text[]), 'That client is such an idiot, I can''t believe they''re still in business.', 'Even in private, informal venting should never include personal insults or disparaging remarks about a client, as this crosses a professionalism boundary regardless of audience.'),
  ('grammar_vocab', 'C2', 'mcq', 'formal_register', 'You need to email an external business partner to formally propose scheduling a call to discuss a sensitive contract issue. Which message is most appropriate?', to_jsonb(ARRAY['We need to talk about the contract, when are you free?','I would like to propose a call at your earliest convenience to discuss a matter relating to our contract that requires your attention.','Got a minute to hop on a call about the contract?','The contract''s an issue, let''s sort it on a call.']::text[]), 'I would like to propose a call at your earliest convenience to discuss a matter relating to our contract that requires your attention.', 'A formal request to an external partner about a sensitive matter should be measured and diplomatic, signaling importance without sounding abrupt.'),
  ('grammar_vocab', 'C2', 'mcq', 'formal_register', 'You made an error that affected a client deliverable and need to formally inform your manager. Which message strikes the appropriate tone?', to_jsonb(ARRAY['Small mix-up on my end, no biggie, I''ll sort it.','I wanted to flag an error I made in the client deliverable, and outline the steps I''m taking to correct it.','Not sure how this happened but it''s not really my fault.','There''s been an issue, someone should probably look into it.']::text[]), 'I wanted to flag an error I made in the client deliverable, and outline the steps I''m taking to correct it.', 'Formally addressing your own mistake to a manager requires direct ownership and a clear corrective plan, avoiding both minimization and deflection.'),
  ('grammar_vocab', 'A1', 'mcq', 'collocations', 'Can you _____ the phone? I''m busy in the kitchen right now.', to_jsonb(ARRAY['answer','respond','reply','listen']::text[]), 'answer', 'The fixed collocation is "answer the phone"; you cannot "respond/reply/listen the phone" in standard English.'),
  ('grammar_vocab', 'A1', 'mcq', 'collocations', 'I need to _____ an email to my colleague before lunch.', to_jsonb(ARRAY['send','do','make','take']::text[]), 'send', 'The fixed collocation is "send an email"; "do/make/take an email" are not correct English.'),
  ('grammar_vocab', 'A1', 'mcq', 'collocations', 'I have to _____ this bill by Friday or my electricity will be cut off.', to_jsonb(ARRAY['pay','do','make','take']::text[]), 'pay', 'The fixed collocation is "pay a bill"; "do/make/take a bill" are not correct English.'),
  ('grammar_vocab', 'A2', 'mcq', 'collocations', 'Please _____ a flight for me on the airline''s website before prices go up.', to_jsonb(ARRAY['book','do','make','take']::text[]), 'book', 'The fixed collocation for reserving travel is "book a flight"; "do/make/take a flight" (in this reserving sense) are not correct English.'),
  ('grammar_vocab', 'A2', 'mcq', 'collocations', 'He was worried he might _____ his job if the company made more cutbacks.', to_jsonb(ARRAY['lose','fail','drop','miss']::text[]), 'lose', 'The fixed collocation is "lose your job"; "fail/drop/miss your job" are not correct English.'),
  ('grammar_vocab', 'A2', 'mcq', 'collocations', 'The manager was out, so the assistant offered to _____ a message for him.', to_jsonb(ARRAY['take','do','make','catch']::text[]), 'take', 'The fixed collocation is "take a message"; "do/make/catch a message" are not correct English.'),
  ('grammar_vocab', 'B1', 'mcq', 'collocations', 'The team worked overtime to _____ the deadline for the project submission.', to_jsonb(ARRAY['meet','catch','achieve','arrive at']::text[]), 'meet', 'The fixed collocation is "meet a deadline"; "catch/achieve/arrive at a deadline" are not correct English.'),
  ('grammar_vocab', 'B1', 'mcq', 'collocations', 'After graduation, we promised to _____ in touch by email and video calls.', to_jsonb(ARRAY['keep','have','do','make']::text[]), 'keep', 'The fixed collocation is "keep in touch"; "have/do/make in touch" are not correct English.'),
  ('grammar_vocab', 'B1', 'mcq', 'collocations', 'Using a template will _____ time when writing weekly reports.', to_jsonb(ARRAY['save','gain','win','earn']::text[]), 'save', 'The fixed collocation is "save time"; "gain/win/earn time" are not correct English.'),
  ('grammar_vocab', 'B2', 'mcq', 'collocations', 'Her parents have decided to _____ a small business from home.', to_jsonb(ARRAY['run','drive','walk','carry']::text[]), 'run', 'The fixed collocation is "run a business"; "drive/walk/carry a business" are not correct English.'),
  ('grammar_vocab', 'B2', 'mcq', 'collocations', 'The company plans to _____ a new product next quarter.', to_jsonb(ARRAY['launch','open','start','birth']::text[]), 'launch', 'The fixed collocation is "launch a product"; "open/start/birth a product" are not correct English.'),
  ('grammar_vocab', 'B2', 'mcq', 'collocations', 'Management needs to _____ this issue before it affects staff morale.', to_jsonb(ARRAY['address','speak','talk','say']::text[]), 'address', 'The fixed collocation is "address an issue"; "speak/talk/say an issue" are not correct English.'),
  ('grammar_vocab', 'C1', 'mcq', 'collocations', 'Investors are advised to _____ caution when trading in volatile markets.', to_jsonb(ARRAY['exercise','do','make','have']::text[]), 'exercise', 'The fixed collocation is "exercise caution"; "do/make/have caution" are not correct English.'),
  ('grammar_vocab', 'C1', 'mcq', 'collocations', 'The two companies decided to _____ a partnership to expand into new markets.', to_jsonb(ARRAY['forge','do','make','take']::text[]), 'forge', 'The fixed collocation is "forge a partnership"; "do/make/take a partnership" are not correct English.'),
  ('grammar_vocab', 'C1', 'mcq', 'collocations', 'The airline managed to _____ the crisis thanks to strong leadership and quick decisions.', to_jsonb(ARRAY['weather','climate','storm','wear']::text[]), 'weather', 'The fixed collocation is "weather a crisis"; "climate/storm/wear a crisis" are not correct English.'),
  ('grammar_vocab', 'C2', 'mcq', 'collocations', 'Some board members privately _____ doubts about the merger''s long-term benefits.', to_jsonb(ARRAY['harbor','carry','keep','do']::text[]), 'harbor', 'The fixed collocation is "harbor doubts"; "carry/keep/do doubts" are not correct English.'),
  ('grammar_vocab', 'C2', 'mcq', 'collocations', 'Employees are expected to _____ discretion when handling confidential client data.', to_jsonb(ARRAY['exercise','do','make','take']::text[]), 'exercise', 'The fixed collocation is "exercise discretion"; "do/make/take discretion" are not correct English.'),
  ('grammar_vocab', 'C2', 'mcq', 'collocations', 'The proposal failed to _____ enough support from senior stakeholders.', to_jsonb(ARRAY['garner','catch','hold','do']::text[]), 'garner', 'The fixed collocation is "garner support"; "catch/hold/do support" are not correct English.');
